create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,role text not null check(role in ('client','driver','admin')),verified boolean default false,created_at timestamptz default now());
create table public.vehicles(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id) on delete cascade,plate text not null,vehicle_type text not null,capacity text,ownership_type text,active boolean default true);
create table public.trips(id uuid primary key default gen_random_uuid(),client_id uuid references public.profiles(id),driver_id uuid references public.profiles(id),category text not null,origin text not null,destination text not null,cargo_description text not null,desired_date date,client_budget numeric(14,2),currency text default 'USD',details text,status text default 'Publicado',created_at timestamptz default now());
create table public.offers(id uuid primary key default gen_random_uuid(),trip_id uuid references public.trips(id) on delete cascade,driver_id uuid references public.profiles(id),amount numeric(14,2) not null,currency text not null,message text,status text default 'Pendiente',created_at timestamptz default now(),unique(trip_id,driver_id));
create table public.trip_messages(id uuid primary key default gen_random_uuid(),trip_id uuid references public.trips(id) on delete cascade,sender_id uuid references public.profiles(id),body text not null,created_at timestamptz default now());
create table public.payment_records(id uuid primary key default gen_random_uuid(),trip_id uuid references public.trips(id),amount numeric(14,2) not null,currency text not null,method text,status text default 'Pendiente',reference text,created_at timestamptz default now());
-- Activar RLS y definir políticas por participante/rol antes de exponer tablas. Nunca usar service_role en el navegador.
